51:     static void createSymbolicLink(String link, String target, int flags)
52:         throws WindowsException
53:     {
54:         try {
55:             CreateSymbolicLink(link, target, flags);
56:         } catch (WindowsException x) {
57:             // Retry if the privilege to create symbolic links is not held
58:             if (x.lastError() == ERROR_PRIVILEGE_NOT_HELD) {
59:                 flags |= SYMBOLIC_LINK_FLAG_ALLOW_UNPRIVILEGED_CREATE;
60:                 try {
61:                     CreateSymbolicLink(link, target, flags);
62:                     return;
63:                 } catch (WindowsException y) {
64:                     // Throw an exception if and only if it is not due to symbolic link creation
65:                     // privilege not being held (ERROR_PRIVILEGE_NOT_HELD) nor the
66:                     // SYMBOLIC_LINK_FLAG_ALLOW_UNPRIVILEGED_CREATE flag not being recognized
67:                     // (ERROR_INVALID_PARAMETER). The latter will occur for Windows builds
68:                     // older than 14972.
69:                     int lastError = y.lastError();
70:                     if (lastError != ERROR_PRIVILEGE_NOT_HELD && lastError != ERROR_INVALID_PARAMETER)
71:                         throw y;
72:                 }
73:             }
